/* ========================================================= */
/* PASTE FULL CSS ANDA DI SINI (Mulai dari Reset margin dsb) */
/* ========================================================= */

/* Menyembunyikan Notifikasi Cookie Bawaan Blogger */
  #cookieChoiceInfo, .cookie-choices-info {
    display: none !important;
  }

/* Reset semua margin/padding bawaan widget Blogger */
.widget, .Widget {
    margin: 0 !important;
    padding: 0 !important;
    line-height: normal !important;
}

/* Menghilangkan border atau background bawaan jika ada */
.section, .widget {
    border: none !important;
}

.section, .region-inner {
    margin: 0 !important;
    padding: 0 !important;
}

:root {
            --primary: #4f46e5;
            --secondary: #9333ea;
            --grad-btn: linear-gradient(90deg, #4f46e5, #9333ea);
            --grad-corp: linear-gradient(135deg, #1e293b 0%, #312e81 100%);
        }

        body {
            font-family: 'Inter', sans-serif;
            background-color: #f8fafc;
            overflow-x: hidden;
        }

		/* ==========================================
           SPLASH SCREEN ANIMATION
           ========================================== */
        @keyframes splash-bg {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .animate-splash-bg { animation: splash-bg 4s ease infinite; }

		/* ==========================================
           DUAL LANGUAGE CONTENT TOGGLE
           ========================================== */
        .konten-en { display: none; }
        body.lang-en .konten-id { display: none !important; }
        body.lang-en .konten-en { display: block !important; }
        body:not(.lang-en) .konten-id { display: block; }
        body:not(.lang-en) .konten-en { display: none !important; }

		/* ==========================================
           WHATSAPP FLOATING WIDGET CSS
           ========================================== */
        .wa-chat-box {
            box-shadow: 0 10px 40px -10px rgba(0,0,0,0.2), 0 0 20px rgba(37, 211, 102, 0.15);
            transform-origin: bottom right;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }
        .wa-hidden {
            opacity: 0;
            visibility: hidden;
            transform: scale(0.8) translateY(20px);
        }
        .wa-visible {
            opacity: 1;
            visibility: visible;
            transform: scale(1) translateY(0);
        }
        /* Custom Scrollbar for Chat */
        .wa-scroll::-webkit-scrollbar { width: 4px; }
        .wa-scroll::-webkit-scrollbar-track { background: transparent; }
        .wa-scroll::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 4px; }

        /* Typing Indicator Animation */
        .typing-dot { animation: typing-bounce 1.4s infinite ease-in-out both; }
        .typing-dot:nth-child(1) { animation-delay: -0.32s; }
        .typing-dot:nth-child(2) { animation-delay: -0.16s; }
        @keyframes typing-bounce {
            0%, 80%, 100% { transform: scale(0); }
            40% { transform: scale(1); }
        }

        /* --- Header Styles & Transitions --- */
        #header-wrapper { transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); }
        #main-navbar { transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); }
        .pill-header { background: rgba(241, 245, 249, 0.85); backdrop-filter: blur(16px); border: 1px solid rgba(255, 255, 255, 0.6); box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.1); }
        .scrolled-header { background: rgba(255, 255, 255, 0.98); backdrop-filter: blur(20px); border-bottom: 1px solid #e2e8f0; box-shadow: 0 4px 20px -2px rgba(0, 0, 0, 0.05); }

       /* --- Desktop Menu & Dropdown (Updated) --- */
        .main-menu { display: flex; gap: 28px; align-items: center; }
        .main-menu li { position: relative; }

        /* Layout ikon & teks menu */
        .main-menu > li > a { font-weight: 600; font-size: 13.5px; color: #1e293b; padding: 6px 0; position: relative; transition: all 0.3s ease; display: flex; align-items: center; }

        /* Animasi Hover (Garis bawah meluas & teks sedikit naik) */
        .main-menu > li > a::after { content: ''; position: absolute; width: 0; height: 2px; bottom: 0; left: 0; background-color: var(--primary); transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1); border-radius: 2px; }
        .main-menu > li > a:hover { color: var(--primary); transform: translateY(-1px); }
        .main-menu > li > a:hover::after { width: 100%; }

        /* Dropdown Menu (Di-kebawahin menjadi top: 135%) */
        .main-menu li ul { position: absolute; top: 135%; left: 0; background: #ffffff; min-width: 240px; box-shadow: 0 20px 40px -10px rgba(0,0,0,0.15); border-radius: 12px; opacity: 0; visibility: hidden; transform: translateY(15px); transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1); padding: 10px; z-index: 9999; border: 1px solid #e2e8f0; }

        /* Jembatan tak terlihat diperlebar agar menu tidak tertutup saat kursor turun */
        .main-menu li ul::before { content: ''; position: absolute; top: -35px; left: 0; width: 100%; height: 35px; }
        .main-menu li:hover ul { opacity: 1; visibility: visible; transform: translateY(0); }

        /* --- Animated Border Sub Menu --- */
        .animated-border-item { position: relative; display: block; border-radius: 0.5rem; overflow: hidden; z-index: 1; margin-bottom: 0.25rem; }
        .animated-border-item::before { content: ''; position: absolute; top: -150%; left: -150%; width: 400%; height: 400%; background: conic-gradient(from 0deg, transparent 60%, #9333ea 80%, #4f46e5 100%); animation: spin-border 3s linear infinite; z-index: -2; opacity: 0; transition: opacity 0.3s ease; }
        .animated-border-item::after { content: ''; position: absolute; inset: 1px; background-color: #ffffff; border-radius: 0.45rem; z-index: -1; transition: background-color 0.3s ease; }
        .animated-border-item:hover::before { opacity: 1; }
        .animated-border-item:hover::after { background-color: #f8fafc; }
        @keyframes spin-border { 100% { transform: rotate(360deg); } }
        .animated-border-content { display: flex; align-items: center; padding: 10px 12px; color: #475569; font-size: 13px; font-weight: 500; position: relative; z-index: 10; transition: color 0.2s; }
        .animated-border-item:hover .animated-border-content { color: var(--primary); }

		/* ==========================================
           MOBILE SIDEBAR CSS (Hover Animation)
           ========================================== */
        /* Animasi Border Melingkar untuk Main Menu Sidebar */
        .mobile-hover-gradient { position: relative; z-index: 1; overflow: hidden; }
        .mobile-hover-gradient::before {
            content: ''; position: absolute; inset: 0;
            border-radius: 0.75rem; /* Sesuai dengan rounded-xl di HTML */
            padding: 1.5px; /* Ketebalan border */
            background: linear-gradient(90deg, #ec4899, #9333ea, #4f46e5, #ec4899);
            background-size: 200% auto;
            -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
            -webkit-mask-composite: xor;
            mask-composite: exclude;
            opacity: 0; transition: opacity 0.3s ease;
            animation: gradient-border-spin 2s linear infinite;
            z-index: -1;
        }
        .mobile-hover-gradient:hover::before { opacity: 1; }

        /* Custom Scrollbar untuk Sidebar agar terlihat rapi */
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: rgba(255, 255, 255, 0.05); border-radius: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.2); border-radius: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, 0.4); }

		/* Custom Scrollbar for Horizontal Scrolling in Academy Mobile */
        .custom-scrollbar-horizontal::-webkit-scrollbar { height: 6px; }
        .custom-scrollbar-horizontal::-webkit-scrollbar-track { background: rgba(255, 255, 255, 0.05); border-radius: 4px; }
        .custom-scrollbar-horizontal::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.2); border-radius: 4px; }
        .custom-scrollbar-horizontal::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, 0.4); }

        /* --- Hero Slider --- */
        .hero-slider-wrapper { position: relative; width: 100%; height: 400px; max-height: 400px; overflow: hidden; background-color: #000; }
        .hero-slider-track { display: flex; width: 100%; height: 100%; transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1); }
        .hero-slide { min-width: 100%; height: 100%; position: relative; }
        .hero-overlay { background: linear-gradient(to right, rgba(15, 23, 42, 0.8) 0%, rgba(30, 58, 138, 0.6) 100%); }

        /* --- Sidebar Luxury --- */
        .sidebar-luxury { background: rgba(15, 23, 42, 0.95); backdrop-filter: blur(20px); border-left: 1px solid rgba(255,255,255,0.1); transition: transform 0.4s cubic-bezier(0.77, 0, 0.175, 1); transform: translateX(100%); }
        body.sidebar-active .sidebar-luxury { transform: translateX(0); }
        .sidebar-overlay { position: fixed; inset: 0; background: rgba(15,23,42,0.7); backdrop-filter: blur(4px); opacity: 0; visibility: hidden; transition: 0.3s; }
        body.sidebar-active .sidebar-overlay { opacity: 1; visibility: visible; }
        .mobile-sub { display: none; padding: 8px 12px 8px 32px; margin-top: 4px; background: rgba(255,255,255,0.05); border-radius: 8px; border-left: 1px solid rgba(255,255,255,0.1); }
        .mobile-sub li { margin-bottom: 2px; }
        .mobile-sub a { display: flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 500; color: #cbd5e1; padding: 8px 0; transition: color 0.2s; }
        .mobile-sub a:hover { color: #ffffff; }



        /* --- Testimonial Carousel --- */
        .testi-track { transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1); }
        .testi-item { width: 100%; flex-shrink: 0; padding: 0 10px; }
        @media (min-width: 1024px) { .testi-item { width: 33.333333%; } }

        /* --- Academy Tabs --- */
        .academy-tab-btn.active { background: var(--primary); color: white; border-color: var(--primary); }
        .academy-tab-content { display: none; animation: fadeIn 0.4s ease; }
        .academy-tab-content.active { display: grid; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

		/* Efek kursor tangan untuk fitur Drag-to-Scroll di desktop */
        .cursor-grab { cursor: grab; }
        .cursor-grabbing { cursor: grabbing !important; }

		/* ==========================================
           ACADEMY BUTTON CSS (Background Animation)
           ========================================== */
        @keyframes bg-shift {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .animate-bg-shift {
            animation: bg-shift 3s ease infinite;
        }

        /* --- Misc UI --- */
        .auth-dropdown-anim { transform-origin: top right; animation: dropdownScale 0.2s ease-out forwards; }
        @keyframes dropdownScale { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        .toggle-checkbox:checked { right: 0; border-color: #4f46e5; }
        .toggle-checkbox:checked + .toggle-label { background-color: #4f46e5; }

		/* ==========================================
           INFINITE MARQUEE (Fix untuk Logo Putih)
           ========================================== */
        .marquee-wrapper { 
            overflow: hidden; 
            white-space: nowrap; 
            width: 100%; 
            padding: 10px 0; /* Menyesuaikan tinggi ruang (padding) */
            position: relative;
            /* Efek gradient bayangan di kiri-kanan agar logo memudar rapi */
            mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
            -webkit-mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
        }

        .marquee-track { 
            display: inline-flex; 
            gap: 5rem; /* Jarak antar logo */
            align-items: center; 
            width: max-content; /* KUNCI RAHASIA: Agar lebar menyesuaikan isi otomatis */
            animation: marquee-scroll 35s linear infinite; 
        }

        .marquee-track:hover { 
            animation-play-state: paused; /* Berhenti saat disorot mouse */
        }

        .marquee-item { 
            display: inline-flex; 
            align-items: center; 
            justify-content: center;
            opacity: 0.4; /* Redupkan logo putih saat normal */
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); 
            cursor: pointer;
        }

        .marquee-item img {
            height: 40px; /* Tinggi logo disesuaikan */
            width: auto;
            object-fit: contain;
        }

        .marquee-item:hover { 
            opacity: 1; /* Menyala terang saat disorot */
            transform: scale(1.1); 
        }

        @keyframes marquee-scroll { 
            0% { transform: translateX(0); } 
            100% { transform: translateX(-50%); } 
        }

		/* ==========================================
           FOOTER CSS
           ========================================== */
        .footer-link:hover { transform: translateX(4px); }

/* ==========================================
   ABOUT US GLOBAL CSS
   ========================================== */
/* Smooth scroll behavior untuk halaman about us */
html {
    scroll-behavior: smooth;
}

/* Memastikan counter-up number memakai font mono agar pergerakannya konstan */
.counter-up {
    font-feature-settings: "tnum";
    font-variant-numeric: tabular-nums;
}

/* ==========================================
   CONTACT US: FLOATING LABELS & ANIMATIONS
   ========================================== */

/* Pastikan input valid/terisi mempertahankan posisi label di atas */
.form-group input:not(:placeholder-shown) + label,
.form-group textarea:not(:placeholder-shown) + label {
    top: 6px !important;
    font-size: 10px !important;
    color: #94a3b8; /* slate-400 */
}

/* Transisi panah dropdown saat fokus */
.form-group select:focus ~ div i {
    transform: rotate(180deg);
    transition: transform 0.3s ease;
}

/* Efek tombol modern */
.btn-animate {
    position: relative;
    overflow: hidden;
}
.btn-animate::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 300%;
    height: 300%;
    background: rgba(255, 255, 255, 0.1);
    transform: translate(-50%, -50%) rotate(45deg) translateY(100%);
    transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}
.btn-animate:hover::after {
    transform: translate(-50%, -50%) rotate(45deg) translateY(-100%);
}


/* ==========================================
   COMING SOON PAGE ANIMATIONS
   ========================================== */

/* Animasi Melayang untuk Roket */
.animate-float {
    animation: floatingRocket 3s ease-in-out infinite;
}

@keyframes floatingRocket {
    0% { transform: translateY(0px); }
    50% { transform: translateY(-15px); }
    100% { transform: translateY(0px); }
}

/* Animasi Latar Belakang Bintang Bergerak */
.stars-bg {
    /* Menggunakan tekstur noise/bintang transparan gratis */
    background-image: url('https://www.transparenttextures.com/patterns/stardust.png');
    background-repeat: repeat;
    animation: moveStars 60s linear infinite;
}

@keyframes moveStars {
    from { background-position: 0 0; }
    to { background-position: -1000px 500px; }
}

/* ==========================================
   404 PAGE ANIMATIONS (Swinging Dead End)
   ========================================== */

/* Pastikan titik ayunan berada di bagian atas papan tempat tali terhubung */
.origin-top {
    transform-origin: top center;
}

/* Animasi ayunan seperti pendulum */
.animate-swing {
    animation: swingSign 4s ease-in-out infinite alternate;
}

@keyframes swingSign {
    0% { transform: rotate(-5deg); }
    100% { transform: rotate(5deg); }
}

/* Optional: Sedikit pergerakan vertikal tambahan agar lebih natural */
.sign-board {
    transition: all 0.3s ease;
}



/* Animasi Fade In Halus untuk Konten Tab Modal */
.animate-fade-in {
    animation: fadeInTab 0.4s ease-out forwards;
}

@keyframes fadeInTab {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}





