body.script:
(function() {
    var urlLang = new URLSearchParams(window.location.search).get('lang');
    var savedLang = localStorage.getItem('prefLang');
    if (urlLang === 'en' || (savedLang === 'en' && urlLang !== 'id')) {
        document.body.classList.add('lang-en');
    }
})();

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
/* ========================================================= */
/* ORLAND MANAGEMENT - GLOBAL JAVASCRIPT                     */
/* Versi Lengkap, Bebas Error, dan Aman untuk Semua Halaman  */
/* ========================================================= */

// --- [ 0. SERVICE WORKER CLEANUP / UNREGISTER ] ---
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.getRegistrations().then(function(registrations) {
    for (var i = 0; i < registrations.length; i++) {
      registrations[i].unregister();
    }
  });
}

// --- [ 1. DYNAMIC HEADER SCROLL (PILL TO WIDTH) ] ---
document.addEventListener('DOMContentLoaded', function () {
  const headerWrapper = document.getElementById('header-wrapper');
  const mainNavbar = document.getElementById('main-navbar');
  if (headerWrapper && mainNavbar) {
    const heroElement = document.getElementById('heroSection') || document.getElementById('about-hero');
    function updateNavbarStyle() {
      let scrollThreshold = heroElement ? heroElement.offsetHeight - 50 : 50;
      if (window.scrollY > scrollThreshold) {
        headerWrapper.classList.replace('top-4', 'top-0'); headerWrapper.classList.remove('px-4', 'lg:px-8');
        mainNavbar.classList.replace('rounded-2xl', 'rounded-none'); mainNavbar.classList.replace('pill-header', 'scrolled-header');
        mainNavbar.style.maxWidth = '100%';
      } else {
        headerWrapper.classList.replace('top-0', 'top-4'); headerWrapper.classList.add('px-4', 'lg:px-8');
        mainNavbar.classList.replace('rounded-none', 'rounded-2xl'); mainNavbar.classList.replace('scrolled-header', 'pill-header');
        mainNavbar.style.maxWidth = '1300px';
      }
    }
    updateNavbarStyle();
    window.addEventListener('scroll', updateNavbarStyle);
  }
});

// --- [ 2. DESKTOP LANGUAGE SELECTION ] ---
function setLang(selected) {
  const en = document.getElementById('lang-en'), id = document.getElementById('lang-id');
  if(!en || !id) return;
  en.classList.remove('opacity-100', 'opacity-50'); id.classList.remove('opacity-100', 'opacity-50');
  if (selected === 'en') { en.classList.add('opacity-100'); id.classList.add('opacity-50'); } 
  else { id.classList.add('opacity-100'); en.classList.add('opacity-50'); }
}

// --- [ 3. AUTH DROPDOWN (DESKTOP) ] ---
let currentAuthMode = 'login'; 
function toggleAuthDropdown(clickedMode = null) {
  const authDropdown = document.getElementById('authDropdown');
  if(!authDropdown) return;
  const isOpen = !authDropdown.classList.contains('hidden');
  if (!clickedMode) return authDropdown.classList.add('hidden');
  if (isOpen) {
    if (clickedMode !== currentAuthMode) { currentAuthMode = clickedMode; updateAuthUI(); } 
    else { authDropdown.classList.add('hidden'); }
  } else {
    currentAuthMode = clickedMode; updateAuthUI();
    authDropdown.classList.remove('hidden', 'auth-dropdown-anim'); 
    void authDropdown.offsetWidth; 
    authDropdown.classList.add('auth-dropdown-anim');
  }
}

function toggleAuthMode() {
  currentAuthMode = currentAuthMode === 'login' ? 'register' : 'login';
  updateAuthUI();
}

function updateAuthUI() {
  const title = document.getElementById('authDropdownTitle'), footerText = document.getElementById('authDropdownFooterText');
  const footerLink = document.getElementById('authDropdownFooterLink'), submitBtn = document.querySelector('#authDropdown button[type="submit"]'); 
  if(!title) return;
  if(currentAuthMode === 'login') {
    title.innerText = "Sign In"; footerText.innerText = "Don't have an account?"; footerLink.innerText = "Register";
    if(submitBtn) submitBtn.innerText = "Sign In";
  } else {
    title.innerText = "Create Account"; footerText.innerText = "Already have an account?"; footerLink.innerText = "Log In";
    if(submitBtn) submitBtn.innerText = "Create Account";
  }
}

// --- [ 4. MOBILE AUTH MODAL & MENU ] ---
function openMobileAuth(mode) {
  const mobileAuthModal = document.getElementById('mobileAuthModal'), mobileAuthCard = document.getElementById('mobileAuthCard');
  toggleSidebar(); switchMobAuth(mode); 
  if(mobileAuthModal && mobileAuthCard) {
    mobileAuthModal.classList.remove('hidden'); mobileAuthModal.classList.add('flex');
    setTimeout(() => { mobileAuthModal.classList.remove('opacity-0'); mobileAuthCard.classList.replace('scale-95', 'scale-100'); }, 10);
    document.body.style.overflow = "hidden";
  }
}

function closeMobileAuth() {
  const mobileAuthModal = document.getElementById('mobileAuthModal'), mobileAuthCard = document.getElementById('mobileAuthCard');
  if(mobileAuthModal && mobileAuthCard) {
    mobileAuthModal.classList.add('opacity-0'); mobileAuthCard.classList.replace('scale-100', 'scale-95');
    setTimeout(() => { mobileAuthModal.classList.add('hidden'); mobileAuthModal.classList.remove('flex'); document.body.style.overflow = ""; }, 300);
  }
}

function switchMobAuth(mode) {
  const tabLogin = document.getElementById('mobTabLogin'), tabReg = document.getElementById('mobTabReg'), nameField = document.getElementById('mobNameField');
  const forgotLink = document.getElementById('mobForgotLink'), submitBtn = document.getElementById('mobSubmitBtn');
  if(!tabLogin) return;
  if(mode === 'login') {
    tabLogin.className = "text-sm font-bold text-indigo-600 border-b-2 border-indigo-600 pb-2 transition-colors";
    tabReg.className = "text-sm font-bold text-slate-400 pb-2 transition-colors border-b-2 border-transparent";
    if(nameField) nameField.classList.add('hidden'); if(forgotLink) forgotLink.classList.remove('hidden'); if(submitBtn) submitBtn.innerText = "Sign In";
  } else {
    tabReg.className = "text-sm font-bold text-indigo-600 border-b-2 border-indigo-600 pb-2 transition-colors";
    tabLogin.className = "text-sm font-bold text-slate-400 pb-2 transition-colors border-b-2 border-transparent";
    if(nameField) nameField.classList.remove('hidden'); if(forgotLink) forgotLink.classList.add('hidden'); if(submitBtn) submitBtn.innerText = "Register";
  }
}

function toggleMobAuthMenu() {
  const actionsMenu = document.getElementById('mob-auth-actions'), chevronIcon = document.getElementById('mob-auth-chevron');
  if (actionsMenu && chevronIcon) {
    if (actionsMenu.classList.contains('hidden')) {
      actionsMenu.classList.replace('hidden', 'grid'); chevronIcon.style.transform = 'rotate(180deg)';
    } else {
      actionsMenu.classList.replace('grid', 'hidden'); chevronIcon.style.transform = 'rotate(0deg)';
    }
  }
}

// --- [ 5. SIDEBAR (MOBILE MENU) ] ---
function toggleSidebar() {
  const isActive = document.body.classList.toggle("sidebar-active");
  document.body.style.overflow = isActive ? "hidden" : "";
}

function toggleSub(id, element) {
  const el = document.getElementById(id);
  if (!el) return;
  const isHidden = el.style.display !== "block";
  el.style.display = isHidden ? "block" : "none";
  const icon = element.querySelector('.sub-toggle');
  if (icon) icon.style.transform = `rotate(${isHidden ? 180 : 0}deg)`;
}

// --- [ 6. HERO SLIDER (HOMEPAGE) ] ---
let currentSlide = 0, slideInterval;
document.addEventListener('DOMContentLoaded', () => {
  const track = document.getElementById('heroSlider'), dotsContainer = document.getElementById('heroDots'), slides = document.querySelectorAll('.hero-slide');
  if (!track || !slides.length) return;
  dotsContainer.innerHTML = [...slides].map((_, i) => `<button onclick="goToSlide(${i})" class="hero-dot transition-all duration-300 rounded-full bg-white ${i === 0 ? 'w-8 h-2.5' : 'w-2.5 h-2.5 opacity-50'}"></button>`).join('');

  window.updateHeroSlider = () => {
    track.style.transform = `translateX(-${currentSlide * 100}%)`;
    document.querySelectorAll('.hero-dot').forEach((dot, i) => dot.className = `hero-dot transition-all duration-300 rounded-full bg-white ${i === currentSlide ? 'w-8 h-2.5 opacity-100' : 'w-2.5 h-2.5 opacity-50'}`);
  };

  window.moveSlide = (dir) => { currentSlide = (currentSlide + dir + slides.length) % slides.length; updateHeroSlider(); resetInterval(); };
  window.goToSlide = (i) => { currentSlide = i; updateHeroSlider(); resetInterval(); };
  const resetInterval = () => { clearInterval(slideInterval); slideInterval = setInterval(() => moveSlide(1), 6000); };
  resetInterval();
});

// --- [ 8. ACADEMY TABS ] ---
function switchAcademyTab(tabId) {
  const activeBtn = document.getElementById(`tab-btn-${tabId}`), activeContent = document.getElementById(`tab-content-${tabId}`);
  document.querySelectorAll('.academy-tab-btn').forEach(btn => btn.className = 'academy-tab-btn px-6 py-2 rounded-full transition-all text-slate-500 hover:text-slate-800 hover:bg-slate-50');
  document.querySelectorAll('.academy-tab-content').forEach(el => el.style.display = 'none');
  if (activeContent) activeContent.style.display = 'flex';
  if (activeBtn) activeBtn.className = `academy-tab-btn active px-6 py-2 rounded-full transition-all text-white bg-gradient-to-r shadow-lg ${tabId === 'actor' ? 'from-violet-600 to-indigo-600 shadow-indigo-500/30' : 'from-pink-500 to-rose-500 shadow-rose-500/30'}`;
}

// --- [ 9. TESTIMONIAL CAROUSEL ] ---
document.addEventListener("DOMContentLoaded", () => {
  const track = document.getElementById("testiTrack"), viewport = document.getElementById("testiViewport");
  if(!track) return;
  const items = [...track.children], itemWidth = items[0].offsetWidth + 24; let index = items.length;
  items.forEach(item => { track.append(item.cloneNode(true)); track.prepend(item.cloneNode(true)); });
  const move = (inst = false) => { track.style.transition = inst ? "none" : "transform 0.5s ease-out"; track.style.transform = `translateX(-${index * itemWidth}px)`; };
  move(true);
  window.moveTesti = (dir) => {
    index += dir; move();
    track.addEventListener("transitionend", () => {
      if (index >= items.length * 2) index = items.length;
      if (index < items.length) index = items.length * 2 - 1;
      move(true);
    }, { once: true });
  };
  let play = setInterval(() => moveTesti(1), 5000);
  if(viewport) { viewport.onmouseenter = () => clearInterval(play); viewport.onmouseleave = () => play = setInterval(() => moveTesti(1), 5000); }
});

// --- [ 10. LANGUAGE ROUTING ] ---
(function () {
  const STORAGE_KEY = 'prefLang', LANG_PARAM = 'lang', params = new URLSearchParams(location.search);
  const getLang = () => params.get(LANG_PARAM) === 'en' || localStorage.getItem(STORAGE_KEY) === 'en' ? 'en' : 'id';
  const updateUI = (lang) => {
    const isEn = lang === 'en'; document.body.classList.toggle('lang-en', isEn);
    const slider = document.getElementById('lang-slider');
    if (slider) { slider.style.transform = `translateX(${isEn ? 0 : 26}px)`; document.getElementById('img-en').classList.toggle('opacity-40', !isEn); document.getElementById('img-id').classList.toggle('opacity-40', isEn); }
    ['en', 'id'].forEach(l => {
      const btn = document.getElementById(`btn-mob-${l}`);
      if (btn) { btn.className = `flex-1 flex items-center justify-center gap-2 py-1.5 rounded-lg text-[11px] font-semibold transition-all ${lang === l ? 'bg-white/10 text-white shadow-sm' : 'bg-transparent text-slate-400 hover:text-white hover:bg-white/5'}`; document.getElementById(`img-mob-${l}`).classList.toggle('opacity-50', lang !== l); }
    });
  };
  const updateLinks = (lang) => {
    document.querySelectorAll('.main-menu a, .sidebar-menu a, .footer-link').forEach(link => {
      let href = link.dataset.originalHref || link.getAttribute('href');
      if (!href || href.startsWith('#') || href.includes(':')) return;
      link.dataset.originalHref = href; const url = new URL(href, location.origin); url.searchParams.delete('m');
      lang === 'en' ? url.searchParams.set('lang', 'en') : url.searchParams.delete('lang');
      link.href = url.pathname + url.searchParams.toString() + url.hash;
    });
  };
  window.switchLanguage = (target) => {
    const next = target || (getLang() === 'en' ? 'id' : 'en'); localStorage.setItem(STORAGE_KEY, next);
    const url = new URL(location.href); next === 'en' ? url.searchParams.set('lang', 'en') : url.searchParams.delete('lang');
    location.href = url.pathname + (url.searchParams.toString() ? '?' + url.searchParams.toString() : '') + url.hash;
  };
  document.addEventListener('DOMContentLoaded', () => {
    const lang = getLang(); updateUI(lang); updateLinks(lang);
    if (params.has('m')) history.replaceState({}, '', location.pathname + (params.toString() ? '?' + params.toString().replace(/&?m=[^&]*/, '') : ''));
  });
})();

// --- [ 11. MOBILE SPLASH SCREEN ] ---
document.addEventListener("DOMContentLoaded", () => {
  const splash = document.getElementById('mobileSplash'), bar = document.getElementById('splashBar'), text = document.getElementById('splashProgress');
  if (!splash || window.innerWidth >= 768) return splash?.remove();
  document.body.style.overflow = 'hidden'; let progress = 0;
  const interval = setInterval(() => {
    progress += Math.floor(Math.random() * 20) + 15;
    if (progress >= 100) {
      progress = 100; clearInterval(interval);
      setTimeout(() => { splash.classList.add('opacity-0'); setTimeout(() => { splash.remove(); document.body.style.overflow = ''; }, 700); }, 400);
    }
    if (bar) bar.style.width = progress + '%'; if (text) text.innerText = progress;
  }, 150);
  setTimeout(() => { if (document.body.contains(splash)) { clearInterval(interval); splash.remove(); document.body.style.overflow = ''; } }, 3500);
});

// --- [ 12. WHATSAPP FLOATING WIDGET & ROUTING ] ---
let currentWaNumber = "", typingTimeout;
function toggleWaPanel() {
  const panel = document.getElementById('waPanel'), mainBtn = document.getElementById('waMainBtn');
  if (!panel) return;
  if (panel.classList.contains('wa-hidden')) {
    panel.classList.replace('wa-hidden', 'wa-visible'); document.getElementById('waAgentView').style.display = 'block'; document.getElementById('waChatView').style.display = 'none';
    if (mainBtn) { mainBtn.style.transform = 'scale(0.8)'; mainBtn.style.opacity = '0.5'; }
  } else {
    panel.classList.replace('wa-visible', 'wa-hidden');
    if (mainBtn) { mainBtn.style.transform = 'scale(1)'; mainBtn.style.opacity = '1'; }
    const waInput = document.getElementById('waInputMessage'); if (waInput) waInput.value = "";
    const status = document.getElementById('waAgentStatus'); if (status) status.innerText = "Online";
  }
}
function openWaChat(dept, name, phone) {
  currentWaNumber = phone;
  const imgSrc = dept === 'Klien' ? 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjXvtPAwLBYAElsJC-29t-WIvfWSYApQeGYsytBBYRze3avMy79zYEsK6po01NGcfth5DudXNpEskR-B5V_Kz_8Oeo8Y_ezdhh_xc6KlKQeo-Xbm694uql-r1weDgx7KNOc-bGz4Kc_hhiLAujxf9ThluxyQ6f1txny-F_Tb3zLTJKTapowPUUFct4YDJE/w100-h80-p-rw/widya-founder.png' : 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhsfdktDBmYKKY2UsBMITrqfW1AhL2M_B2ucJTtuwLx9bb830Q2KsMmsERMAAP986O_gBAoKR_qiIWj5mXzwRe3WGfvD6FCJwDuRlLKxH52pKaRajiKUNdoZvM6Ajs6DyJ-IfKExYvNV5By4qPSNzyZJBc3QNfyq5E3F_jjXUV26ZMX9ZIUqh3szgoOmeU/w100-h80-p-rw/1000142150.png';
  document.getElementById('waAgentImg').src = imgSrc; document.getElementById('waAgentName').innerText = name;
  const deptEn = dept === 'Klien' ? 'Client' : 'Talent';
  document.getElementById('waBubbleName').innerText = name; document.getElementById('waBubbleRoleId').innerText = dept; document.getElementById('waBubbleRoleEn').innerText = deptEn;
  document.getElementById('waTextNameId').innerText = name; document.getElementById('waTextDeptId').innerText = dept; document.getElementById('waTextNameEn').innerText = name; document.getElementById('waTextDeptEn').innerText = deptEn;
  const now = new Date(); document.getElementById('waTime').innerText = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
  document.getElementById('waAgentView').style.display = 'none'; document.getElementById('waChatView').style.display = 'flex';
  setTimeout(() => { const input = document.getElementById('waInputMessage'); if (input) input.focus(); }, 300);
}
function backToWaAgents() {
  document.getElementById('waChatView').style.display = 'none'; document.getElementById('waAgentView').style.display = 'block';
  document.getElementById('waInputMessage').value = ""; document.getElementById('waAgentStatus').innerText = "Online";
}
function waTypingEffect() {
  const status = document.getElementById('waAgentStatus'), input = document.getElementById('waInputMessage');
  if (!status || !input) return;
  if (input.value.trim().length > 0) {
    status.innerHTML = '<span class="text-slate-500 italic">mengetik pesan...</span>'; clearTimeout(typingTimeout);
    typingTimeout = setTimeout(() => { status.innerHTML = 'Online'; }, 1500);
  } else { status.innerHTML = 'Online'; }
}
function handleWaEnter(e) { if (e.key === 'Enter') sendWaMessage(); }
function sendWaMessage() {
  const input = document.getElementById('waInputMessage'); if (!input || input.value.trim() === "") return;
  window.open(`https://wa.me/${currentWaNumber}?text=${encodeURIComponent(input.value.trim())}`, '_blank');
  input.value = ""; toggleWaPanel();
}
window.smartWaLink = function (dept, name, phone) {
  if (window.innerWidth < 1024) { window.open(`https://wa.me/${phone}?text=${encodeURIComponent(`Halo Kak ${name}, saya ingin berdiskusi mengenai layanan departemen ${dept} di Orland Management. Bisa dibantu?`)}`, '_blank'); } 
  else if (typeof triggerWaPopup === 'function') { triggerWaPopup(dept, name, phone); }
};
window.triggerWaPopup = function (dept, name, phone) {
  const container = document.getElementById('wa-widget-container'), panel = document.getElementById('waPanel'), mainBtn = document.getElementById('waMainBtn');
  if (container) container.classList.remove('hidden', 'lg:block');
  if (panel && panel.classList.contains('wa-hidden')) {
    panel.classList.replace('wa-hidden', 'wa-visible');
    if (mainBtn) { mainBtn.style.transform = 'scale(0.8)'; mainBtn.style.opacity = '0.5'; }
  }
  typeof openWaChat === 'function' ? openWaChat(dept, name, phone) : smartWaLink(dept, name, phone);
};

// --- [ 13. INFINITY MARQUEE LOGIC ] ---
document.addEventListener('DOMContentLoaded', function() {
  const track = document.getElementById('clientMarquee'); if(!track) return;
  const originalItems = Array.from(track.children); if(originalItems.length === 0) return;
  let currentItems = [...originalItems];
  while (currentItems.length < 10) { originalItems.forEach(item => { const clone = item.cloneNode(true); track.appendChild(clone); currentItems.push(clone); }); }
  currentItems.forEach(item => { const clone = item.cloneNode(true); clone.setAttribute('aria-hidden', 'true'); track.appendChild(clone); });
});

// --- [ 14. BACK TO TOP BUTTON ] ---
document.addEventListener('DOMContentLoaded', function () {
  const scrollToTopBtn = document.getElementById('scrollToTopBtn'); if(!scrollToTopBtn) return;
  window.addEventListener('scroll', function () {
    if (window.scrollY > 300) { scrollToTopBtn.classList.replace('opacity-0', 'opacity-100'); scrollToTopBtn.classList.replace('invisible', 'visible'); scrollToTopBtn.classList.replace('translate-y-4', 'translate-y-0'); } 
    else { scrollToTopBtn.classList.replace('opacity-100', 'opacity-0'); scrollToTopBtn.classList.replace('visible', 'invisible'); scrollToTopBtn.classList.replace('translate-y-0', 'translate-y-4'); }
  });
});

// --- [ 15. INTERACTIVE STATS COUNTER ] ---
document.addEventListener('DOMContentLoaded', function () {
  const counters = document.querySelectorAll('.counter-up'); if(counters.length === 0) return;
  const counterObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const targetElement = entry.target;
        const updateCount = () => {
          const target = +targetElement.getAttribute('data-target'), count = +targetElement.innerText, inc = target / 200;
          if (count < target) { targetElement.innerText = Math.ceil(count + inc); setTimeout(updateCount, 20); } else { targetElement.innerText = target; }
        };
        updateCount(); observer.unobserve(targetElement);
      }
    });
  }, { threshold: 0.5 });
  counters.forEach(counter => counterObserver.observe(counter));
});

