// --- [ SSO URL TOKEN CATCHER ] ---
function cekUrlTokenEmail() {
  const urlParams = new URLSearchParams(window.location.search);

  // =========================================================
  // 0. PENANGKAP TOKEN LOGIN DARI SSO (TAMBAHKAN KODE INI)
  // =========================================================
  const loginToken = urlParams.get('token');
  const loginRole = urlParams.get('role');

  if (loginToken && loginRole) {
      // 1. Susun data user dari URL
      const userData = {
          token: loginToken,
          role: loginRole,
          user_type: loginRole,
          id: urlParams.get('user_id') || '',
          full_name: urlParams.get('name') || 'User',
          first_name: urlParams.get('name') || 'User',
          email: urlParams.get('email') || ''
      };

      // 2. Simpan ke Local Storage Blogger
      localStorage.setItem('orland_sso_user', JSON.stringify(userData));

      // 3. Bersihkan URL (Hapus token dari address bar agar rapi dan aman)
      window.history.replaceState({}, document.title, window.location.pathname);

      // 4. Render UI Logged In dan hentikan eksekusi fungsi
      renderLoggedInUI(userData);
      return; 
  }
  // =========================================================


  const activationToken = urlParams.get('activation_token');
  const resetToken = urlParams.get('reset_token');
  const inviteToken = urlParams.get('invite');

  if (inviteToken) {
    window.orlandInviteToken = inviteToken; 
    window.history.replaceState({}, document.title, window.location.pathname);

    const container = document.getElementById('authHybridContainer');
    if (container) container.classList.remove('hidden');

    switchAuthView('view-register', 'register');
    showAuthAlert("✨ Anda mendapat undangan VIP (Jalur Agensi). Silakan buat akun Anda di bawah ini.", false);

    setTimeout(() => {
        const roleTalent = document.querySelector('input[name="reg-role"][value="talent"]');
        if (roleTalent) roleTalent.checked = true;

        const roleGrid = document.querySelector('input[name="reg-role"]').closest('.grid.grid-cols-3');
        if (roleGrid) {
            const labelAts = roleGrid.previousElementSibling;
            if (labelAts) {
                labelAts.innerHTML = "<span class='konten-id'>Pendaftaran via Undangan Agensi (VIP)</span><span class='konten-en'>Agency Invitation Registration (VIP)</span>";
                labelAts.className = "block text-[11px] font-black text-amber-600 uppercase mb-2";
            }
            roleGrid.style.display = 'none';
        }
    }, 50);
  } 
  else if (activationToken) {
    window.history.replaceState({}, document.title, window.location.pathname);
    handleAktivasiOtomatis(activationToken);
  } 
  else if (resetToken) {
    window.history.replaceState({}, document.title, window.location.pathname);
    window.orlandResetToken = resetToken; 
    const container = document.getElementById('authHybridContainer');
    if (container) container.classList.remove('hidden');
    switchAuthView('view-new-password', 'new-password');
    showAuthAlert("Silakan buat kata sandi baru Anda.", false);
  }
}

async function handleAktivasiOtomatis(token) {
  const container = document.getElementById('authHybridContainer');
  if (container) container.classList.remove('hidden');
  document.querySelectorAll('.auth-view').forEach(el => el.classList.add('hidden'));
  setModalLoading(true, "Mengesahkan akun Anda...");
  try {
    const res = await fetch(`${SSO_URL}/api/auth/verify-activation`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ token: token }), credentials: 'include' });
    const data = await res.json();
    if (res.ok && data.status === 'ok') {
      updateLoadingText("Akun Berhasil Diaktifkan!");
      setTimeout(() => { closeAuthUI(); window.location.reload(); }, 1500);
    } else {
      setModalLoading(false); switchAuthView('view-login', 'login'); showAuthAlert(data.message || "Link aktivasi kadaluarsa.", true);
    }
  } catch(e) {
    setModalLoading(false); switchAuthView('view-login', 'login'); showAuthAlert("Koneksi gagal. Coba lagi nanti.", true);
  }
}

