  if(document.getElementById('mob-user-avatar')) document.getElementById('mob-user-avatar').src = avatarUrl;
}

// --- [ CEK SESI BACKGROUND ] ---
async function checkUserSession() {
  try {
    const controller = new AbortController(), timeoutId = setTimeout(() => controller.abort(), 5000);
    const res = await fetch(`${SSO_URL}/api/auth/me`, { method: 'GET', credentials: 'include', signal: controller.signal });
    clearTimeout(timeoutId);
    const contentType = res.headers.get("content-type");
    if (res.ok && contentType && contentType.includes("application/json")) {
      const data = await res.json();
      if(data.status === 'ok' || data.user) { 
        const userData = data.user || data; 
        userData.redirect_url = data.redirect_url;

        // --- [PERBAIKAN 2: EKSTRAKSI TOKEN DARI URL] ---
        // Backend mengirimkan token secara tersembunyi di dalam redirect_url
        if (data.redirect_url && data.redirect_url.includes('token=')) {
            try {
                const urlObj = new URL(data.redirect_url);
                userData.token = urlObj.searchParams.get('token');
                userData.role = urlObj.searchParams.get('role') || userData.user_type;
            } catch(e) {}
        } else {
            userData.role = userData.user_type;
        }
        // ------------------------------------------------

        localStorage.setItem('orland_sso_user', JSON.stringify(userData));
        renderLoggedInUI(userData); return;
      }
    }
  } catch (e) { }

  localStorage.removeItem('orland_sso_user');
  const skeleton = document.getElementById('auth-loading-skeleton'), elGuest = document.getElementById('auth-guest'), elLoggedIn = document.getElementById('auth-logged-in');
  if (skeleton) skeleton.classList.add('hidden');
  if (elLoggedIn) elLoggedIn.classList.add('hidden');
  if (elGuest) { elGuest.classList.remove('hidden'); elGuest.classList.add('flex', 'animate-in', 'fade-in', 'duration-300'); }

  const mobLoading = document.getElementById('mob-auth-loading'), mobGuest = document.getElementById('mob-auth-guest'), mobLoggedIn = document.getElementById('mob-auth-loggedin');
  if (mobLoading) mobLoading.classList.add('hidden');
  if (mobLoggedIn) { mobLoggedIn.classList.replace('flex', 'hidden'); }
  if (mobGuest) { mobGuest.classList.replace('hidden', 'block'); }
}

