// Bypass token
function renderCaptcha(mode) {
  if (mode === 'login') instantLoginToken = "disabled";
  if (mode === 'register') instantRegToken = "disabled";
}

async function waitForTurnstileToken(mode) {
  let token = mode === 'login' ? instantLoginToken : instantRegToken;
  if (token) return token;
  for (let i = 0; i < 35; i++) {
    await new Promise(resolve => setTimeout(resolve, 100));
    token = mode === 'login' ? instantLoginToken : instantRegToken;
    if (token) return token;
  }
  return null;
}

// --- [ CORE API CALLER ] ---
async function handleApiAuth(event, action) {
  if(event && event.preventDefault) event.preventDefault();
  let btn, oriText;
  if (event && event.target && event.target.querySelector) {
    btn = event.target.querySelector('button[type="submit"]');
    if (btn) { oriText = btn.innerHTML; btn.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i> Menunggu Verifikasi...'; btn.disabled = true; }
  }

  const startTime = Date.now();
  setModalLoading(true, "Mengecek keamanan turnstile...");

  const mode = action === 'login-password' ? 'login' : 'register';

  let token = "disabled_turnstile_token"; // Auto Inject Fake Token

  const elapsedTime = Date.now() - startTime, minWait = 5000; 
  if (elapsedTime < minWait) {
    updateLoadingText("Memvalidasi identitas aman...");
    await new Promise(r => setTimeout(r, minWait - elapsedTime));
  }

  if (!token) return abortAuthProcess("Gagal verifikasi keamanan. Mohon Tunggu 1-2 Detik dan coba lagi.", btn, oriText, mode);

  updateLoadingText("Menyambungkan ke SSO...");
  let endpoint = "", payload = {};

  if (action === 'login-password') {
    endpoint = "/api/auth/login-password";
    payload = { identifier: document.getElementById('login-id').value, password: document.getElementById('login-pass').value, turnstile_token: token };
  } else if (action === 'register') {
    endpoint = "/api/auth/register";
    payload = { fullName: document.getElementById('reg-name').value, email: document.getElementById('reg-email').value, phone: document.getElementById('reg-wa').value, password: document.getElementById('reg-pass').value, role: document.querySelector('input[name="reg-role"]:checked').value, turnstile_token: token, invite_token: window.orlandInviteToken || undefined };
  } else {
    if (action === 'request-otp') { endpoint = "/api/auth/request-otp"; payload = { identifier: document.getElementById('otp-id').value, purpose: 'login' }; }
    else if (action === 'verify-otp') { endpoint = "/api/auth/login-otp"; payload = { identifier: document.getElementById('otp-id').value, otp: document.getElementById('otp-code').value }; }
    else if (action === 'login-pin') { endpoint = "/api/auth/login-pin"; payload = { identifier: document.getElementById('pin-id').value, pin: document.getElementById('pin-code').value }; }
    else if (action === 'request-reset') { endpoint = "/api/auth/request-reset"; payload = { identifier: document.getElementById('forgot-id').value }; }
    else if (action === 'submit-new-password') { endpoint = "/api/auth/reset-password"; payload = { token: window.orlandResetToken, new_password: document.getElementById('new-reset-pass').value }; }
  }

  try {
    const res = await fetch(`${SSO_URL}${endpoint}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload), credentials: 'include' });
    const data = await res.json();
    if (res.ok && data.status === 'ok') {
      if (btn) { btn.innerHTML = '<i class="fa-solid fa-check-circle"></i> Berhasil...'; btn.style.background = "#10b981"; }

      if (action === 'login-password' || action === 'verify-otp' || action === 'login-pin') {
        updateLoadingText("Akses diberikan!");
        setTimeout(() => { window.location.reload(); }, 1000);
      } else if (action === 'request-otp') {
        setModalLoading(false);
        showAuthAlert("Kode OTP telah dikirim ke email Anda.", false);
        switchAuthView('view-otp', 'otp');
        startOtpTimer();
        resetButton(btn, oriText);
      } else if (action === 'request-reset') {
        setModalLoading(false);
        showAuthAlert("Tautan reset kata sandi telah dikirim ke email Anda.", false);
        resetButton(btn, oriText);
      } else if (action === 'submit-new-password') {
        setModalLoading(false);
        showAuthAlert("Kata sandi berhasil diubah! Silakan masuk kembali.", false);
        setTimeout(() => { switchAuthView('view-login', 'login'); }, 2000);
        resetButton(btn, oriText);
      } else if (action === 'register') {
        setModalLoading(false);
        showAuthAlert("Registrasi berhasil! Silakan cek kotak masuk email Anda untuk mengaktifkan akun.", false);
        setTimeout(() => { switchAuthView('view-login', 'login'); }, 3000);
        resetButton(btn, oriText);
      }
    } else {
      abortAuthProcess(data.message || "Akses ditolak.", btn, oriText, mode);
    }
  } catch (err) {
    abortAuthProcess("Koneksi SSO terputus.", btn, oriText, mode);
  }
}

function abortAuthProcess(msg, btn, oriText, mode) {
  setModalLoading(false); showAuthAlert(msg, true);
  resetButton(btn, oriText);
}

function resetButton(btn, oriText) { if (btn && oriText) { btn.innerHTML = oriText; btn.disabled = false; } }

function togglePassword(inputId, iconId) {
  const input = document.getElementById(inputId), icon = document.getElementById(iconId);
  if (!input || !icon) return;
  if (input.type === 'password') { input.type = 'text'; icon.className = 'fa-solid fa-eye-slash text-indigo-600'; } 
  else { input.type = 'password'; icon.className = 'fa-solid fa-eye text-slate-400'; }
}

function handleResendOtp(e) { if(e) e.preventDefault(); handleApiAuth(e, 'request-otp'); }

function startOtpTimer() {
  let timeLeft = 180;
  const timerDisplay = document.getElementById('otp-timer'), resendBtn = document.getElementById('btn-resend-otp'), verifyForm = document.getElementById('form-verify-otp');
  if (resendBtn) resendBtn.classList.add('hidden'); if (timerDisplay) timerDisplay.classList.remove('hidden'); if (verifyForm) verifyForm.classList.remove('hidden');
  clearInterval(otpTimerInterval);
  otpTimerInterval = setInterval(() => {
    timeLeft--;
    let m = Math.floor(timeLeft / 60).toString().padStart(2, '0'), s = (timeLeft % 60).toString().padStart(2, '0');
    if (timerDisplay) timerDisplay.innerText = `${m}:${s}`;
    if (timeLeft <= 0) {
      clearInterval(otpTimerInterval);
      if (timerDisplay) timerDisplay.classList.add('hidden');
      if (resendBtn) resendBtn.classList.remove('hidden');
    }
  }, 1000);
}

async function handleLogout() {
  const logoutOverlayHTML = `
  <div id="globalLogoutOverlay" class="fixed inset-0 z-[999999] bg-white/80 backdrop-blur-md flex flex-col items-center justify-center animate-in fade-in duration-500">
      <div class="relative">
          <div class="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          <i class="fa-solid fa-shield-halved absolute inset-0 flex items-center justify-center text-indigo-600 text-xl"></i>
      </div>
      <h2 class="text-xl font-black text-slate-900 mt-6 tracking-tight">Logout Berhasil</h2>
      <p class="text-slate-500 text-xs font-bold uppercase tracking-widest mt-2">Sampai Jumpa Lagi</p>
  </div>`;
  document.body.insertAdjacentHTML('beforeend', logoutOverlayHTML);
  try { await fetch(`${SSO_URL}/api/auth/logout`, { method: 'POST', credentials: 'include' }); } catch (e) {}
  localStorage.removeItem('orland_sso_user');
  setTimeout(() => { window.location.reload(); }, 1500);
}

// --- [ 18. ROLE GATEKEEPER & REDIRECTOR ] ---
function enforceRoleAccess() {
  const path = window.location.pathname.toLowerCase();

  // Daftar halaman yang dilindungi beserta Role yang diizinkan
  const protectedRoutes = {
    '/p/profile.html': ['talent', 'admin', 'super_admin'],
    '/p/agency-dashboard.html': ['agency', 'admin', 'super_admin'],
    '/p/client-dashboard.html': ['client', 'admin', 'super_admin'],
    '/p/admin-dashboard.html': ['admin', 'super_admin']
  };

  // Cek apakah halaman saat ini ada di daftar halaman yang dilindungi
  let allowedRoles = null;
  for (const route in protectedRoutes) {
      if (path.includes(route)) {
          allowedRoles = protectedRoutes[route];
          break;
      }
  }

  if (allowedRoles) {
    const ssoUserStr = localStorage.getItem('orland_sso_user');

    // Jika belum login tapi mencoba buka halaman dashboard
    if (!ssoUserStr) {
        window.location.href = "https://orlandmanagement.com";
        return;
    }

    // Jika sudah login, cek role-nya
    try {
        const user = JSON.parse(ssoUserStr);
        const role = (user.role || user.user_type || 'talent').toLowerCase();

        // Jika role tidak ada di daftar yang diizinkan
        if (!allowedRoles.includes(role)) {
            alert("🛑 Akses Ditolak: Anda tidak memiliki izin untuk membuka halaman ini.");
            window.location.href = getDefaultDashboard(role); // Tendang kembali ke dashboard yang benar
        }
    } catch(e) {}
  }
}

// Jalankan seketika saat file diload
enforceRoleAccess();


// --- [ FUNGSI MEMBUKA MODAL EDIT PROFIL GLOBAL ] ---
function openGlobalEditProfile() {
    const ssoUserStr = localStorage.getItem('orland_sso_user');
    if (!ssoUserStr) {
        alert("Sesi tidak ditemukan, silakan login ulang.");
        return;
    }

    const user = JSON.parse(ssoUserStr);

    // 1. Isi data ke form
    document.getElementById('edit-first-name').value = user.first_name || '';
    document.getElementById('edit-last-name').value = user.last_name || '';
    document.getElementById('edit-display-email').innerText = user.email || '-';
    document.getElementById('edit-display-wa').innerText = user.phone || 'Belum diatur';

    // 2. Atur Status Badge Email (Asumsi: Email dari SSO selalu verified)
    document.getElementById('badge-email-verified').classList.remove('hidden');

    // 3. Atur Status Badge WA
    if (user.phone && user.phone.length > 8) {
        document.getElementById('badge-wa-verified').classList.remove('hidden');
        document.getElementById('badge-wa-unverified').classList.add('hidden');
    } else {
        document.getElementById('badge-wa-verified').classList.add('hidden');
        document.getElementById('badge-wa-unverified').classList.remove('hidden');
    }

    // 4. Ubah Judul Modal
    const titleEl = document.getElementById('authTitle');
    if (titleEl) titleEl.innerHTML = "<span class='konten-id'>Pengaturan Profil SSO</span><span class='konten-en'>SSO Profile Settings</span>";

    // 5. Tampilkan Modal dan arahkan ke view Edit
    const container = document.getElementById('authHybridContainer');
    if (container) container.classList.remove('hidden');

    // Sembunyikan semua view lain, munculkan view edit
    document.querySelectorAll('.auth-view').forEach(el => el.classList.add('hidden'));
    document.getElementById('view-edit-profile').classList.remove('hidden');
}

// --- [ FUNGSI MENYIMPAN PERUBAHAN KE SSO API ] ---
async function handleUpdateProfileGlobal(e) {
    e.preventDefault();

    const ssoUserStr = localStorage.getItem('orland_sso_user');
    if (!ssoUserStr) return;
    const user = JSON.parse(ssoUserStr);

    const btn = document.getElementById('btn-save-profile');
    const oriText = btn.innerHTML;
    btn.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Menyimpan...";
    btn.disabled = true;

    const payload = {
        first_name: document.getElementById('edit-first-name').value,
        last_name: document.getElementById('edit-last-name').value
    };

    try {
        // Tembak langsung ke API SSO Anda
        const res = await fetch('https://sso.orlandmanagement.com/api/auth/update-sso', {
            method: 'PUT',
            headers: { 
                'Content-Type': 'application/json',
                'Authorization': 'Bearer ' + user.token
            },
            body: JSON.stringify(payload)
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.message || `Server Error ${res.status}`);
        }

        const result = await res.json();

        if (result.status === 'ok') {
            // Update LocalStorage agar UI web langsung berubah
            user.first_name = payload.first_name;
            user.last_name = payload.last_name;
            user.full_name = (payload.first_name + ' ' + payload.last_name).trim();
            localStorage.setItem('orland_sso_user', JSON.stringify(user));

            showAuthAlert("Profil berhasil diperbarui!", false);

            // Tutup modal dan refresh halaman setelah 1.5 detik agar UI (seperti nama di header) terupdate
            setTimeout(() => {
                closeAuthUI();
                window.location.reload(); 
            }, 1500);

        } else {
            showAuthAlert("Gagal: " + (result.message || "Kesalahan Server"), true);
        }
    } catch (err) {
        showAuthAlert("Kesalahan Jaringan. Pastikan internet Anda stabil.", true);
    } finally {
        btn.innerHTML = oriText;
        btn.disabled = false;
    }
}


